// Real-time model for the exploded-view sequence.
// CONCEPT MODEL: public/models/angostura-uno-concept.glb is generated by
// tools/3d/build_concept.py. Its proportions are typical of an in-ear
// monitor and are NOT product specs. It is replaced by an export from the
// real CAD when that exists (docs/PHASE3-3D-BRIEF.md).
import {
  ACESFilmicToneMapping,
  Box3,
  Color,
  DirectionalLight,
  Group,
  Mesh,
  PerspectiveCamera,
  PMREMGenerator,
  Scene,
  SRGBColorSpace,
  Vector3,
  WebGLRenderer,
  type Material,
  type Object3D,
} from 'three';
import { RoomEnvironment } from 'three/examples/jsm/environments/RoomEnvironment.js';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import { MeshoptDecoder } from 'three/examples/jsm/libs/meshopt_decoder.module.js';
import type { StageState } from './stage-scroll';

const MODEL_URL = '/models/angostura-uno-concept.glb';
// The model is authored in millimetres; the scene works in units of 10 mm.
const MM = 0.1;
// Node name → how far it travels along the model's explode axis (mm),
// and which callout lights it. The ear tip travels with the nozzle callout.
const PARTS: Record<string, { offset: number; callout: string }> = {
  shell: { offset: -7, callout: 'shell' },
  faceplate: { offset: 21, callout: 'faceplate' },
  nozzle: { offset: -19, callout: 'nozzle' },
  eartip: { offset: -30, callout: 'nozzle' },
  drivers: { offset: 2, callout: 'drivers' },
  crossover: { offset: 11.5, callout: 'crossover' },
};
// Exploded, the parts span about 72 mm, centred about 13 mm behind the origin.
const EXPLODED_SPAN = 72 * MM;
const EXPLODED_CENTRE = -13 * MM;

const css = (name: string) => getComputedStyle(document.documentElement).getPropertyValue(name).trim();
const lerp = (a: number, b: number, t: number) => a + (b - a) * t;

interface Part {
  node: Object3D;
  rest: number;
  offset: number;
  callout: string;
  /** centre of the part in its own local space, for the leader line */
  anchor: Vector3;
  materials: Material[];
}

export async function initStage3D(stage: HTMLElement, state: StageState) {
  const canvas = stage.querySelector<HTMLCanvasElement>('.stage__canvas')!;
  const view = stage.querySelector<HTMLElement>('.stage__view')!;
  const leader = stage.querySelector<SVGSVGElement>('.stage__leader')!;
  const leaderLine = leader.querySelector('line')!;
  const leaderDot = leader.querySelector('circle')!;
  const callouts = [...stage.querySelectorAll<HTMLElement>('.callout')];

  const gltf = await new GLTFLoader().setMeshoptDecoder(MeshoptDecoder).loadAsync(MODEL_URL);

  const renderer = new WebGLRenderer({ canvas, antialias: !state.lean, alpha: true, powerPreference: 'high-performance' });
  renderer.setPixelRatio(Math.min(devicePixelRatio, state.lean ? 1.5 : 2));
  renderer.outputColorSpace = SRGBColorSpace;
  renderer.toneMapping = ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.25;

  const scene = new Scene();
  const pmrem = new PMREMGenerator(renderer);
  scene.environment = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
  pmrem.dispose();

  const camera = new PerspectiveCamera(30, 1, 0.1, 50);
  camera.position.set(0, 0, 9);

  // studio lighting: warm key, cool rim
  const key = new DirectionalLight(new Color('#fff1dc'), 2.4);
  key.position.set(3, 4, 5);
  const rim = new DirectionalLight(new Color('#cfe0ff'), 1.6);
  rim.position.set(-4, 2, -4);
  scene.add(key, rim);

  // model > inner (slides to keep the exploded view centred) > glTF scene
  const model = new Group();
  const inner = new Group();
  gltf.scene.scale.setScalar(MM);
  inner.add(gltf.scene);
  model.add(inner);
  scene.add(model);

  scene.updateMatrixWorld(true);
  const parts: Part[] = [];
  for (const [name, { offset, callout }] of Object.entries(PARTS)) {
    const node = gltf.scene.getObjectByName(name);
    if (!node) continue;
    // Each part gets its own material instances so it can be dimmed alone.
    const clones = new Map<Material, Material>();
    node.traverse((child) => {
      if (!(child instanceof Mesh)) return;
      const source = child.material as Material;
      if (!clones.has(source)) {
        const clone = source.clone();
        clone.transparent = true;
        if (state.lean && 'clearcoat' in clone) (clone as Material & { clearcoat: number }).clearcoat = 0;
        clones.set(source, clone);
      }
      child.material = clones.get(source)!;
    });
    const anchor = node.worldToLocal(new Box3().setFromObject(node).getCenter(new Vector3()));
    // The model's explode axis (Blender +Z, through the faceplate) is each
    // node's local +Y after the glTF exporter's Y-up conversion.
    parts.push({ node, rest: node.position.y, offset, callout, anchor, materials: [...clones.values()] });
  }
  // the part each callout's leader line points at (first match, so the
  // nozzle callout points at the nozzle, not the ear tip)
  const targets = callouts.map((el) => parts.find((p) => p.callout === el.dataset.part));

  let width = 0;
  let height = 0;
  const resize = () => {
    width = view.clientWidth;
    height = view.clientHeight;
    renderer.setSize(width, height, false);
    camera.aspect = width / height;
    camera.updateProjectionMatrix();
  };
  new ResizeObserver(resize).observe(view);
  resize();

  const dim = parseFloat(css('--dim')) || 0.35;
  const world = new Vector3();
  const start = performance.now();

  const frame = () => {
    const { p, explode, active } = state;
    const portrait = width < height;
    const t = state.lean ? 0 : (performance.now() - start) / 1000;
    const lit = active === -1 ? null : callouts[active].dataset.part;

    // hero: model sits right (or low on portrait); sequence: centred
    const heroness = 1 - Math.min(1, p / 0.1);
    // visible half-width of the view at the model's depth
    const halfW = Math.tan((camera.fov * Math.PI) / 360) * camera.position.z * camera.aspect;
    model.position.x = portrait ? 0 : lerp(halfW * 0.22, halfW * 0.62, heroness);
    model.position.y = portrait ? lerp(0.5, -1.5, heroness) : 0;
    const scale = (portrait ? 0.62 : Math.min(1, halfW / 3.4)) * lerp(0.9, 0.95, heroness);
    // exploded, shrink so the whole row of parts fits the view width
    const fit = Math.min(scale, (halfW * 2 * 0.86) / EXPLODED_SPAN);
    model.scale.setScalar(lerp(scale, fit, explode));
    inner.position.z = -EXPLODED_CENTRE * explode;

    // rotation: one full turn across the hero, a slow idle drift, and a
    // side-on view when exploded so the parts read along one axis
    const side = -1.05;
    const turn = Math.min(1, p / 0.1) * Math.PI * 2;
    model.rotation.y = lerp(0.65 + Math.sin(t * 0.4) * 0.12 + turn, side + Math.sin(t * 0.3) * 0.04, explode);
    model.rotation.x = lerp(0.25, 0.18, explode);

    for (const part of parts) {
      part.node.position.y = part.rest + part.offset * explode;
      const target = lit === null || part.callout === lit ? 1 : dim;
      for (const m of part.materials) m.opacity = lerp(m.opacity, target, 0.18);
    }

    renderer.render(scene, camera);

    // leader line from the active part to its callout card
    const target = active === -1 ? undefined : targets[active];
    const on = !!target && explode > 0.9;
    leader.classList.toggle('is-on', on);
    if (on && target) {
      target.node.localToWorld(world.copy(target.anchor)).project(camera);
      const x = (world.x * 0.5 + 0.5) * width;
      const y = (-world.y * 0.5 + 0.5) * height;
      const card = callouts[active].getBoundingClientRect();
      const box = view.getBoundingClientRect();
      leaderDot.setAttribute('cx', x.toFixed(1));
      leaderDot.setAttribute('cy', y.toFixed(1));
      leaderLine.setAttribute('x1', x.toFixed(1));
      leaderLine.setAttribute('y1', y.toFixed(1));
      leaderLine.setAttribute('x2', (card.left - box.left + 4).toFixed(1));
      leaderLine.setAttribute('y2', (card.top - box.top).toFixed(1));
    }
  };

  stage.addEventListener('stage:frame', frame);
  frame();
  document.documentElement.classList.add('stage-ready');
}
